def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Convert relative path to absolute
    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path

    # Normalize the path to remove redundant slashes
    path = path.replace('//', '/')

    # Split into components
    components = path.split('/')

    # Start resolution
    current = '/'
    link_count = 0
    i = 0

    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]

            # Get remaining components
            remaining = components[i + 1:]

            # Resolve the symlink target
            if target.startswith('/'):
                # Absolute target
                current = target
            else:
                # Relative target - relative to the directory containing the link
                link_dir = current.rsplit('/', 1)[0]
                if link_dir == '':
                    link_dir = '/'
                if link_dir == '/':
                    current = '/' + target
                else:
                    current = link_dir + '/' + target

            # Split the target and continue from there
            target_components = current.split('/')
            components = target_components + remaining
            current = '/'
            i = 0
            continue

        i += 1

    # Return the result, removing trailing slash except for '/'
    if current == '/':
        return '/'
    else:
        return current.rstrip('/')

